/**
 * [INPUT]: 依赖真实设置分区与项目字段合同、范围数据和 ui.js。
 * [OUTPUT]: 导出设置分区、项目字段与池或设备的资源模式。
 * [POS]: 产品设置表现层；不收集真实密钥，不执行远端连接。
 * [PROTOCOL]: Update this header on change, then check AGENTS.md
 */
import * as U from './ui.js';
import { getWorkspaceProjects, getWorkspaces } from './entry-data.js';
const { icon, btn, field, input, esc, select, panel, pageHeader, sectionTitle, kv, badge, table } = U;
const workspaceSections = [['general', '基本信息'], ['members', '成员与邀请'], ['ai', 'AI 规划'], ['emissary', 'Emissary 升级'], ['integrations', 'Webhook'], ['signing', '签名'], ['tokens', '访问令牌'], ['credentials', 'Git 凭据'], ['audit', '审计'], ['lifecycle', '生命周期']];
const projectSections = [['general', '基本信息'], ['members', '成员'], ['resources', '资源与凭据'], ['signing', '默认签名'], ['integrations', 'Webhook'], ['lifecycle', '生命周期']];
export function currentWorkspace(state) { return getWorkspaces(state).find(space => state.workspaceId ? space.id === state.workspaceId : space.name === state.workspace) || getWorkspaces(state)[0]; }
export function projectFields(state, project = null, section = 'all') {
    const values = state.projectSettings?.[project?.id] || {}, general = section !== 'resources', resources = section !== 'general';
    return `${general ? field('项目名称', `<input class="input" name="name" value="${esc(values.name ?? project?.name ?? '')}" maxlength="100" placeholder="例如 Nova Desktop" required>`, '不超过 100 UTF-8 字节。') + field('Git 仓库地址', `<input class="input" name="repository_url" value="${esc(values.repository_url ?? project?.repository ?? (project ? `https://git.example/${project.repo}.git` : ''))}" placeholder="https://git.example/team/project.git" required>`, '密钥通过独立凭据引用传入。HTTP 仅在明确输入该协议时使用。') : ''}
    ${resources ? `<div class="grid-2">${field('源码凭据', select('credential_id', values.credential_id || '匿名读取', ['匿名读取', 'git/orbital-readonly', 'git/team-readonly']))}${field('设备授权模式', select('node_access_mode', values.node_access_mode === '指定设备' ? 'nodes' : values.node_access_mode === '节点池' ? 'pools' : values.node_access_mode || 'pools', [{ value: 'pools', label: '节点池' }, { value: 'nodes', label: '指定设备' }]))}</div><fieldset><legend>授权资源</legend><div class="entry-grants">${[['pools','apple','Apple 原生构建池'],['pools','windows','Windows 原生构建池'],['pools','linux','Linux 原生构建池'],['nodes','studio','Mac Studio'],['nodes','windows-builder','Windows Builder']].map(([mode,id,name]) => `<label data-project-resource-mode="${mode}"><input class="checkbox" type="checkbox" name="node_access_ids" value="${id}" ${(values.node_access_ids || (project?.id === 'orbital' ? ['apple','windows'] : [])).includes(id) ? 'checked' : ''}>${name}</label>`).join('')}</div><p class="field-help">选择与授权模式一致的资源。原生目标只使用已授权设备能力。</p></fieldset>${field('签名方案引用', input('signing_profiles', values.signing_profiles || (project?.id === 'orbital' ? 'signing/orbital-macos, signing/orbital-windows' : '')), '多个方案以逗号分隔。')}` : ''}
    ${general ? field('规划模型', select('model_profile_id', values.model_profile_id || '工作空间默认模型', ['工作空间默认模型', 'Planner / production', 'Planner / review'])) + field('构建上下文', `<textarea name="build_context" rows="4" placeholder="例如：工具链要求、项目目录与发布约束">${esc(values.build_context || '')}</textarea>`, '作为项目规划上下文，不替代每次构建要求。') : ''}
    ${resources ? field('额外源码凭据绑定', `<textarea name="source_credentials" rows="2" placeholder='[{"repository_url":"https://git.example/sub.git","credential_id":"git-demo"}]'>${esc(Array.isArray(values.source_credentials) ? JSON.stringify(values.source_credentials, null, 2) : values.source_credentials || '[]')}</textarea>`, 'JSON 数组。子模块分别绑定 repository_url 与 credential_id，URL 不包含密钥。') : ''}`;
}
function members(state, project) {
    const rows = currentWorkspace(state)?.id !== 'orbital' && !project ? [] : project ? [['linzhiyuan', '管理员'], ['chenyu', '操作员'], ['zhouke', '只读成员']] : [['linzhiyuan', '所有者'], ['chenyu', '管理员'], ['zhouke', '成员']];
    if (project) for (const member of state.demoMembers || []) { if (member.projectId === project.id) { const previous = rows.find(row => row[0] === member.username); if (previous) previous[1] = member.role; else rows.push([member.username, member.role]); } }
    return sectionTitle(project ? '项目授权' : '工作空间成员', btn(project ? '添加成员' : '创建邀请', project ? 'manage-project-member' : 'manage-invitation', 'secondary', 'plus')) + table(['用户名', '角色', '范围'], rows.map(([name, role]) => [name, badge(role, 'neutral'), project ? esc(project.name) : esc(state.workspace)])) + `<p class="field-help mt">${project ? '项目角色为管理员、操作员、只读成员。' : '工作空间角色为所有者、管理员、成员。邀请仅授予工作空间角色。'}</p>${!project ? `<h3 class="mt">邀请链接</h3>${(state.demoInvitations || []).filter(item => item.workspaceId === currentWorkspace(state).id).map(item => `<div class="list-row"><span>${esc(item.role)} · ${item.expires} 天</span><span class="mono">#join/${item.id}</span></div>`).join('') || '<p class="field-help">没有待接受的本地演示邀请。</p>'}` : ''}`;
}
function integrations(state, project) {
    const key = project ? `project:${project.id}` : `workspace:${currentWorkspace(state)?.id}`, endpoints = (state.demoWebhooks || []).filter(item => item.scope === key);
    return sectionTitle('Webhook', btn('添加端点', 'manage-webhook', 'secondary', 'plus', `data-scope="${esc(key)}"`)) + `<p>个人邮件订阅在账户设置中配置。Webhook 使用当前${project ? '项目' : '工作空间'}范围，默认关闭。</p>${endpoints.map(item => `<div class="list-row"><div><h3>${esc(item.name)}</h3><p>${esc(item.url)}</p><small>${esc(Array.isArray(item.event_types) ? item.event_types.join(', ') : item.event_types)}</small></div>${badge(item.enabled ? '已开启' : '关闭', item.enabled ? 'success' : 'neutral')}${btn('投递记录', 'webhook-history', 'ghost', 'arrow', `data-id="${item.id}"`)}</div>`).join('') || U.empty('还没有端点', '添加虚构地址，预览事件类型与一次密钥。')}`;
}
function modelSettings(state) {
    const values = state.managementValues?.[currentWorkspace(state)?.id]?.ai || {};
    return `<form class="entry-management-form" data-form="manage-ai">${field('配置名称', `<input class="input" name="name" maxlength="100" required value="${esc(values.name || 'Planner / production')}">`)}${field('API 协议', select('api', values.api || 'OpenAI Chat Completions', ['OpenAI Chat Completions', 'OpenAI Responses', 'Anthropic Messages']))}${field('服务地址', `<input class="input" name="base_url" type="url" value="${esc(values.base_url || 'https://ai.example/v1')}" required>`)}${field('模型名称', `<input class="input" name="model" maxlength="200" value="${esc(values.model || 'planner-model')}" required>`, '由供应商定义，可填写完整名称。')}<div class="grid-2">${field('调用次数', `<input class="input" type="number" name="max_calls" min="1" max="100" value="${esc(values.max_calls || 20)}" required>`)}${field('超时（秒）', `<input class="input" type="number" name="timeout_seconds" min="30" max="3600" value="${esc(values.timeout_seconds || 600)}" required>`)}${field('上下文窗口', `<input class="input" type="number" name="context_window" min="1024" value="${esc(values.context_window || 128000)}" required>`)}${field('输出 Token', `<input class="input" type="number" name="max_tokens" min="256" value="${esc(values.max_tokens || 8192)}" required>`)}</div>${field('推理等级', select('thinking_level', values.thinking_level || 'off', ['off', 'minimal', 'low', 'medium', 'high', 'xhigh', 'max']))}<details><summary>显式兼容参数</summary>${field('系统角色', select('compat_system_role', values.compat_system_role || 'system', ['system', 'developer']))}${field('推理参数', select('compat_thinking_format', values.compat_thinking_format || 'none', ['none', 'reasoning_effort', 'enable_thinking', 'thinking']))}${field('输出参数', select('compat_max_tokens_field', values.compat_max_tokens_field || 'max_tokens', ['max_tokens', 'max_completion_tokens']))}</details><p class="notice">真实系统在此安全输入 API Key。原型只保存非敏感配置，连接与模型调用不执行。</p><button class="btn primary" type="submit">保存演示配置 ${icon('check', 16)}</button></form>`;
}
function lifecycle(state, project) {
    const key = project?.id || currentWorkspace(state)?.id, operationKey = project ? `project:${project.id}` : `workspace:${key}`, status = state.demoLifecycle?.[operationKey] || 'active';
    return sectionTitle('生命周期') + `${kv('对象', esc(project?.name || state.workspace))}${kv('标识', esc(project?.slug || key))}${kv('状态', badge(({active:'活动',archived:'已归档',draining:'排空中',deleting:'删除中'})[status], status === 'active' ? 'success' : 'warning'))}<p class="field-help">先阅读影响和当前操作，再明确确认。以下只改变本地状态，不声称真实排空或删除已完成。</p>${state.lifecycleOperations?.[operationKey] ? btn('查看当前操作与恢复动作', 'lifecycle-current', 'secondary', 'clock', `data-scope="${operationKey}"`) : ''}<div class="row wrap mt">${btn(status === 'archived' ? '恢复对象' : '归档对象', 'manage-lifecycle', 'secondary', 'folder', `data-scope="${key}" data-project-scope="${!!project}" data-verb="${status === 'archived' ? 'restore' : 'archive'}"`)}${btn('删除对象', 'manage-lifecycle', 'danger', 'close', `data-scope="${key}" data-project-scope="${!!project}" data-verb="delete"`)}</div>`;
}
export function renderManagement(state, project = null) {
    const section = project ? state.projectSettingsSection || 'general' : state.managementSection || 'general', sections = project ? projectSections : workspaceSections, current = currentWorkspace(state);
    let content;
    if (section === 'general') content = project ? `<form class="entry-management-form" data-form="manage-project">${projectFields(state, project, 'general')}<button class="btn primary" type="submit">保存项目 ${icon('check', 16)}</button></form>` : `<form class="entry-management-form" data-form="manage-workspace">${field('工作空间名称', `<input class="input" name="name" value="${esc(current?.name || '')}" required maxlength="100">`)}${field('标识', `<input class="input mono" value="${esc(current?.id || '')}" readonly>`, '标识保持稳定。')}<button class="btn primary" type="submit">保存名称 ${icon('check', 16)}</button></form>`;
    else if (section === 'resources') content = `<form class="entry-management-form" data-form="manage-project">${projectFields(state, project, 'resources')}<button class="btn primary" type="submit">保存资源授权 ${icon('check', 16)}</button></form><h3 class="mt">镜像仓库与 BuildKit Secret</h3><p class="field-help">按项目隔离。真实凭据只能在受授权的产品表单输入。</p>${btn('预览镜像凭据字段', 'manage-image-credentials', 'secondary', 'key')}`;
    else if (section === 'members') content = members(state, project);
    else if (section === 'integrations') content = integrations(state, project);
    else if (section === 'ai') content = modelSettings(state);
    else if (section === 'lifecycle') content = lifecycle(state, project);
    else if (section === 'signing') content = sectionTitle(project ? '项目默认签名' : '签名凭据与方案', btn('查看签名方案', 'manage-signing', 'secondary', 'shield')) + `<p>${project ? '先读取签名预览与必需凭据，再修改默认方案。' : '签名材料与方案分别配置。历史构建固定材料版本。'}</p>` + table(['方案引用', '用途', '状态'], project?.id === 'orbital' || !project && current?.id === 'orbital' ? [['signing/orbital-macos','macOS Developer ID',badge('示例已授权','success')], ['signing/orbital-windows','Windows Authenticode',badge('示例已授权','success')]] : []);
    else if (section === 'emissary') content = sectionTitle('Emissary 升级') + kv('统一产品版本', '0.2.5') + kv('当前发布', badge('示例就绪', 'success')) + `<p>版本差异只提示。工作空间管理员明确选择设备后发起升级。</p><div class="mt">${btn('选择设备并确认', 'node-update', 'secondary', 'refresh')}</div><p class="field-help">设备公开入口在系统管理员范围配置，不随工作空间权限开放。</p>`;
    else if (section === 'tokens') content = sectionTitle('访问令牌', btn('创建令牌', 'manage-token', 'secondary', 'key')) + table(['名称', '项目范围', '能力'], (state.demoTokens || []).filter(item => item.workspaceId === currentWorkspace(state)?.id).map(item => [esc(item.name), esc(item.projects.join(', ')), esc(item.scopes.join(', '))])) + `<p class="field-help">没有项目授权时只开放 read。完整令牌只显示一次。原型不生成可访问服务的凭据。</p>`;
    else if (section === 'credentials') content = sectionTitle('Git 凭据', btn('预览凭据字段', 'manage-credential', 'secondary', 'key')) + table(['名称', '类型', '存储'], current?.id === 'orbital' ? [['git/orbital-readonly', 'HTTPS', '加密存储 · 示例'], ['git/team-readonly', 'SSH', '加密存储 · 示例']] : []) + '<p class="field-help">密钥不回显，不写入原型存储。仓库 URL 禁止包含密钥。</p>';
    else content = sectionTitle('操作审计') + table(['时间', '动作', '操作者', '对象'], current?.id === 'orbital' ? [['2026-11-26 14:23', 'project.created', 'linzhiyuan', 'Orbital Desktop'], ['2026-11-26 14:28', 'release.created', 'linzhiyuan', '2.4.0']] : []) + '<p class="field-help">审计仅呈现已有记录。未提供的证据不推造。</p>';
    return pageHeader(project ? 'PROJECT / SETTINGS' : 'WORKSPACE / SETTINGS', sections.find(([id]) => id === section)?.[1] || '设置', `${esc(project?.name || current?.name || '')} · 当前范围`) + `<div class="entry-settings-content">${panel(content)}</div>`;
}

export function syncProjectResourceMode(root) {
    root.querySelectorAll('[name=node_access_mode]').forEach(input => { const form = input.form, mode = input.value === 'nodes' || input.value === '指定设备' ? 'nodes' : 'pools'; form?.querySelectorAll('[data-project-resource-mode]').forEach(label => { const shown = label.dataset.projectResourceMode === mode; label.hidden = !shown; label.querySelector('input').disabled = !shown; }); });
}
